verify.cmd:
node --experimental-strip-types --no-warnings --import ./scripts/probe-ts.mjs -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const hook=(()=>{try{return fs.readFileSync("scripts/probe-ts.mjs","utf8")}catch(e){return null}})()
if(hook===null)fail("scripts/probe-ts.mjs is gone, so no probe can import a real module and every row is back to grepping source for how the code is spelled")
if(!/^registerHooks\(/m.test(hook))fail("scripts/probe-ts.mjs imports registerHooks and never CALLS it at the top level, so the hook is never installed and an @/ import or an extensionless relative import inside a probe throws instead of resolving")
if(/\bload\s*\(/.test(hook))fail("scripts/probe-ts.mjs registers a load hook, so it is a transform and a probe no longer measures the file the product ships. It is a resolver, and only a resolver")
const led=require("./scripts/lib/ledger.mjs").loadBacklog()
const running=led.entries.filter((e)=>e.verify&&typeof e.verify.cmd==="string"&&e.verify.cmd.includes("probe-ts.mjs"))
if(running.length<7)fail("only "+running.length+" rows import a real module through scripts/probe-ts.mjs; the audit converted seven, so the ledger has gone back to spelling one row at a time")
import("@/lib/events/calendar-grid.ts").then((grd)=>{
const host=grd.calendarChrome(true)
const marks=grd.HOST_DRAWN_CONTROL_MARKS||{}
const con=(()=>{try{return fs.readFileSync("components/spaces/calendar-console.tsx","utf8").replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")}catch(e){return ""}})()
if(!marks.viewSwitch||!marks.monthJump)fail("the grid/list switcher and the month jump no longer name the marker their host must carry, so nothing checks that the console draws the two controls it takes: that is the reachable dead end this row closed, with its gate removed")
for(const key of Object.keys(host)){
if(host[key]!==false)continue
if(!marks[key]||!con.includes(marks[key]))fail("the console takes "+key+" off the grid and draws nothing in its place, which is the reachable dead end this row closed: in List inside the console there is then no way back to the month and no way to move more than one month, and closing the console is the only exit")
}
if(host.monthTitle!==false||host.paging!==false)fail("the grid draws its own month title or paging cluster inside the console again, so the console pays twice for chrome the host already draws")
const page=grd.calendarChrome(false)
if(page.monthTitle!==true||page.paging!==true)fail("a grid under NO host draws neither its month title nor its paging cluster, so a bare mount -- the Space settings calendar -- has no month and nothing above it to replace one")
const ws=(()=>{try{return fs.readFileSync("components/spaces/calendar-workspace.tsx","utf8").replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")}catch(e){return ""}})()
const pageMarks=grd.PAGE_DRAWN_CONTROL_MARKS||{}
const pageIsHost=/[\s{]hostChrome[\s/>]/.test(ws.replace(/hostChrome=\{[^}]*\}/g," "))
if(pageIsHost){
for(const key of Object.keys(host)){
if(host[key]!==false)continue
if(key==="viewSwitch")continue
if(!pageMarks[key]||!ws.includes(pageMarks[key]))fail("the page takes "+key+" off its grid unconditionally and draws nothing in its place: on the page that is a month grid with no month, no paging and no way to leave the month it opened on, which is the LIVE-475 dead end with the page in the console role")
}
if(!/data-calendar-page-header/.test(ws))fail("the page grid gives up its chrome and there is no page control bar to have taken it")
}
const doc=fs.readFileSync("docs/EVENTS-CALENDAR.md","utf8")
if(/four views from one segmented control/.test(doc))fail("EVENTS-CALENDAR.md claims one segmented control again; it is a Guest preview button beside a three-way box")
if(/Guest and Admin start on the same month and then each keeps its own position/.test(doc))fail("EVENTS-CALENDAR.md says the two panels keep separate months again; the workspace owns month and hands it to both")
}).catch((e)=>{console.error(String(e&&e.message||e));process.exit(1)})'
